contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 v) public {
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(v <= balBefore);
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;
        bool frozenBefore = c.frozenAccount(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool ok = c.burn(v); if (__ESBMC_reverted()) return;
        assert(
            frozenBefore &&
            ok &&
            c.frozenAccount(address(this)) &&
            c.balanceOf(address(this)) + v == balBefore &&
            c.totalSupply() + v == supplyBefore
        );
    }
    receive() external payable {}
}

